    ts = {(p[0]-ap(q)[0], p[1]-ap(q)[1]) for p in cen.values() for q in cen.values()}
    for t in ts:
        g = {}
        for k, p in cen.items():
            q = ap(p); q = (q[0]+t[0], q[1]+t[1])
            if q in pos: g[k] = pos[q]
        if (M == MS[0] and t == (0, 0)): continue
